"use client";

import {
    TrendingUp,
    FileCheck,
    Clock,
    ArrowUpRight,
    ArrowDownRight,
    Plus,
    Zap,
    Wallet,
    Award,
    Flame,
    Target
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useSimulation } from "@/components/SimulationProvider";
import useSWR from "swr";
import { fetcher } from "@/lib/fetcher";

export default function Dashboard() {
    const { currentUser } = useSimulation();

    const { data: qCertificates } = useSWR(`/api/certificates?userId=${currentUser.id}&role=${currentUser.role}`, fetcher);
    const { data: qCustomers } = useSWR(`/api/customers?userId=${currentUser.id}&role=${currentUser.role}`, fetcher);
    const { data: financialData } = useSWR(currentUser?.id ? `/api/financials?userId=${currentUser.id}` : null, fetcher);
    const availableBalance = financialData?.available || 0;

    const certCount = qCertificates?.length || 0;
    const custCount = qCustomers?.length || 0;

    const xpGoal = currentUser.level === "Bronze" ? 1000 : currentUser.level === "Prata" ? 2500 : 5000;
    const xpProgress = Math.min((currentUser.xp / xpGoal) * 100, 100);

    return (
        <div className="p-4 md:p-6 lg:p-8 space-y-8">

            {/* ── Hero ── */}
            <section className="relative overflow-hidden bg-card dark:bg-gradient-to-br dark:from-[#151B28] dark:to-[#0B0F1A] rounded-2xl border border-[var(--border)] shadow-premium transition-all duration-500">
                <div className="absolute top-0 right-0 w-1/3 h-full bg-primary/5 dark:bg-primary/10 blur-[100px] pointer-events-none" />
                <div className="absolute -bottom-24 -left-24 w-64 h-64 bg-primary/5 dark:bg-blue-500/5 blur-[80px] pointer-events-none rounded-full" />

                <div className="relative z-10 px-8 py-8 lg:px-10 lg:py-10">
                    <div className="flex flex-wrap items-center justify-between gap-6 mb-8">
                        <div className="space-y-1">
                            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-[var(--muted)] opacity-80">Dashboard Visão Geral</p>
                            <h1 className="text-2xl lg:text-3xl font-black tracking-tight text-[var(--foreground)]">
                                Bem-vindo, <span className="text-primary">{currentUser.name.split(' ')[0]}</span>
                            </h1>
                        </div>

                        <div className="flex items-center gap-3">
                            <div className="flex items-center gap-2 bg-white dark:bg-white/5 border border-[var(--border)] px-4 py-2 rounded-xl shadow-sm">
                                <span className={cn(
                                    "px-2 py-0.5 text-[9px] font-black uppercase tracking-wider rounded-md",
                                    currentUser.level?.toLowerCase() === 'ouro' ? "bg-amber-500/10 text-amber-600" :
                                        currentUser.level?.toLowerCase() === 'prata' ? "bg-slate-500/10 text-slate-600" :
                                            "bg-primary/10 text-primary"
                                )}>
                                    Nível {currentUser.level}
                                </span>
                                <div className="h-3 w-px bg-[var(--border)]" />
                                <span className="flex items-center gap-1.5 text-amber-600 dark:text-amber-400 text-[11px] font-bold">
                                    <Flame size={14} className="animate-pulse" />
                                    5 Dias
                                </span>
                            </div>

                            <button className="bg-primary hover:bg-primary/90 text-white px-5 py-2.5 rounded-xl font-bold text-xs shadow-lg shadow-primary/10 transition-all flex items-center gap-2 active:scale-95">
                                <Plus size={16} />
                                Nova Emissão
                            </button>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-center">
                        <div className="lg:col-span-12 xl:col-span-8">
                            <div className="bg-[var(--accent)]/50 dark:bg-white/5 border border-[var(--border)] rounded-2xl p-6 relative group overflow-hidden">
                                <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                                    <Zap size={80} className="text-primary" />
                                </div>

                                <div className="flex flex-wrap items-end justify-between gap-4 mb-4">
                                    <div className="space-y-1">
                                        <h2 className="text-sm font-bold text-[var(--foreground)]">Progresso de Nível</h2>
                                        <p className="text-xs text-[var(--muted)]">Faltam <span className="font-bold text-primary">{xpGoal - currentUser.xp} XP</span> para {currentUser.level?.toLowerCase() === 'bronze' ? 'Prata' : currentUser.level?.toLowerCase() === 'prata' ? 'Ouro' : 'Mestre'}</p>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-2xl font-black text-primary leading-none">{currentUser.xp}</p>
                                        <p className="text-[10px] font-black text-[var(--muted)] uppercase tracking-widest mt-1">Total XP</p>
                                    </div>
                                </div>

                                <div className="relative pt-1">
                                    <div className="overflow-hidden h-3 text-xs flex rounded-full bg-slate-200 dark:bg-slate-800 shadow-inner">
                                        <div
                                            style={{ width: `${xpProgress}%` }}
                                            className="shadow-glow-primary shadow-primary/20 flex flex-col text-center whitespace-nowrap text-white justify-center bg-primary transition-all duration-1000 relative"
                                        >
                                            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-[shimmer_2s_infinite]" />
                                        </div>
                                    </div>
                                    <div className="flex justify-between text-[10px] font-bold text-[var(--muted)] mt-2 uppercase tracking-widest">
                                        <span>{currentUser.level}</span>
                                        <span>{currentUser.level?.toLowerCase() === 'bronze' ? 'Prata' : currentUser.level?.toLowerCase() === 'prata' ? 'Ouro' : 'Mestre'}</span>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="lg:col-span-12 xl:col-span-4 grid grid-cols-2 gap-4">
                            <div className="bg-card border border-[var(--border)] rounded-2xl p-5 shadow-premium-sm hover:shadow-premium transition-all">
                                <div className="size-10 rounded-xl bg-amber-500/10 text-amber-600 flex items-center justify-center mb-3">
                                    <Award size={20} />
                                </div>
                                <p className="text-[10px] font-black text-[var(--muted)] uppercase tracking-widest mb-1">Badge</p>
                                <p className="text-xs font-bold text-[var(--foreground)] truncate">
                                    {currentUser.equippedBadge ? `"${currentUser.equippedBadge}"` : '"Nenhum"'}
                                </p>
                            </div>
                            <div className="bg-card border border-[var(--border)] rounded-2xl p-5 shadow-premium-sm hover:shadow-premium transition-all">
                                <div className="size-10 rounded-xl bg-emerald-500/10 text-emerald-600 flex items-center justify-center mb-3">
                                    <Zap size={20} />
                                </div>
                                <p className="text-[10px] font-black text-[var(--muted)] uppercase tracking-widest mb-1">Missões</p>
                                <p className="text-xs font-bold text-[var(--foreground)]">2 / 3 Completas</p>
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            {/* ── KPI Grid ── */}
            <div className="grid grid-cols-2 lg:grid-cols-6 gap-6">
                <div className="col-span-2 lg:col-span-3">
                    <StatCard
                        title="Vendas do Mês"
                        value={currentUser.sales_total.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                        change="+12.5%"
                        isPositive={true}
                        icon={TrendingUp}
                        color="primary"
                        isLarge
                    />
                </div>
                <div className="col-span-2 lg:col-span-3">
                    <div className="grid grid-cols-2 gap-4 h-full">
                        <StatCard
                            title="Sua Wallet"
                            value={availableBalance.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                            change="+R$ 0,00"
                            isPositive={true}
                            icon={Wallet}
                            color="emerald"
                        />
                        <StatCard
                            title="Certificados"
                            value={certCount.toString()}
                            change={`${custCount} clientes`}
                            isPositive={true}
                            icon={FileCheck}
                            color="indigo"
                        />
                    </div>
                </div>
            </div>

            {/* ── Bottom Grid: Missions + Seals ── */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                {/* Missions — 2/3 width */}
                <div className="lg:col-span-2 bg-[var(--card)] rounded-none border border-[var(--border)] p-6 shadow-sm">
                    <div className="flex items-center justify-between mb-5">
                        <div>
                            <h3 className="text-base font-black tracking-tight text-[var(--foreground)]">Missões Ativas</h3>
                            <p className="text-[10px] text-[var(--muted)] font-bold uppercase tracking-widest mt-0.5">Conclua para ganhar XP extra</p>
                        </div>
                        <span className="px-2 py-1 bg-primary/5 text-primary text-[10px] font-bold rounded-lg border border-primary/10">
                            1/3 Completas
                        </span>
                    </div>

                    <div className="space-y-3">
                        <MissionItem title="Venda em Sequência" desc="Realize 1 venda hoje para manter sua ofensiva de 5 dias." progress={100} xp={50} completed />
                        <MissionItem title="Especialista PJ" desc="Emita 3 certificados PJ nesta semana." progress={66} xp={150} />
                        <MissionItem title="Indicação Premiada" desc="Indique 1 contador para a plataforma." progress={0} xp={500} />
                    </div>
                </div>

                <div className="bg-[var(--card)] rounded-none border border-[var(--border)] shadow-sm flex flex-col">
                    <div className="px-5 pt-5 pb-4 border-b border-[var(--border)]">
                        <h3 className="text-[var(--foreground)] text-[11px] font-black uppercase tracking-widest flex items-center gap-2">
                            <Award className="text-primary" size={14} />
                            Selos Equipados
                        </h3>
                    </div>

                    <div className="p-4 space-y-3 flex-1">
                        {/* Active seal */}
                        <div className="p-4 rounded-none bg-primary/5 dark:bg-white/5 border border-primary/10 dark:border-white/10 flex items-center gap-3 relative hover:bg-primary/10 dark:hover:bg-white/10 transition-all cursor-pointer">
                            <div className={cn(
                                "size-10 rounded-none flex items-center justify-center shrink-0",
                                currentUser.level?.toLowerCase() === 'ouro' ? "bg-amber-400/20 text-amber-600" :
                                    currentUser.level?.toLowerCase() === 'prata' ? "bg-slate-400/20 text-slate-600" :
                                        "bg-orange-400/20 text-orange-600"
                            )}>
                                <Zap size={18} />
                            </div>
                            <div className="min-w-0">
                                <p className="text-[11px] font-bold text-slate-900 dark:text-white uppercase tracking-tight">Selo {currentUser.level}</p>
                                <p className="text-[10px] text-[var(--muted)] truncate">Benefícios de nível {currentUser.level} ativos</p>
                            </div>
                            <div className="absolute -top-1 -right-1 size-2.5 bg-emerald-400 rounded-full border-2 border-[var(--card)] dark:border-slate-900" />
                        </div>

                        {/* Empty slot */}
                        <div className="p-4 rounded-none border border-dashed border-[var(--border)] dark:border-slate-700 flex items-center gap-3 opacity-50 hover:opacity-100 transition-all cursor-pointer">
                            <div className="size-10 rounded-none bg-[var(--accent)] dark:bg-slate-800 text-[var(--muted)] flex items-center justify-center shrink-0">
                                <Award size={18} />
                            </div>
                            <div>
                                <p className="text-[11px] font-bold text-slate-900 dark:text-slate-300 uppercase tracking-tight">Vazio</p>
                                <p className="text-[10px] text-[var(--muted)]">Equipe um selo de buff</p>
                            </div>
                        </div>

                        {/* Quick stats strip */}
                        <div className="pt-3 border-t border-[var(--border)] grid grid-cols-2 gap-3">
                            <div className="text-center">
                                <p className="text-lg font-black text-slate-900 dark:text-white">{currentUser.xp.toLocaleString()}</p>
                                <p className="text-[9px] font-bold text-[var(--muted)] uppercase tracking-widest">XP Total</p>
                            </div>
                            <div className="text-center">
                                <p className="text-lg font-black text-slate-900 dark:text-white">{custCount}</p>
                                <p className="text-[9px] font-bold text-[var(--muted)] uppercase tracking-widest">Clientes</p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

function MissionItem({ title, desc, progress, xp, completed }: any) {
    return (
        <div className={cn(
            "px-5 py-4 rounded-xl border transition-all flex items-center gap-4 group",
            completed
                ? "bg-emerald-500/5 border-emerald-500/15"
                : "bg-card border-[var(--border)] hover:border-primary/30 hover:shadow-premium-sm"
        )}>
            <div className={cn(
                "size-10 rounded-xl flex items-center justify-center shrink-0 transition-colors",
                completed ? "bg-emerald-500/15 text-emerald-600" : "bg-[var(--accent)] text-[var(--muted)] group-hover:bg-primary/10 group-hover:text-primary"
            )}>
                {completed ? <FileCheck size={18} /> : <Clock size={18} />}
            </div>
            <div className="flex-1 min-w-0">
                <div className="flex justify-between items-center mb-1.5">
                    <p className="font-bold text-[14px] tracking-tight text-[var(--foreground)] truncate">{title}</p>
                    <div className="flex items-center gap-1.5 px-2 py-0.5 bg-primary/10 rounded-md">
                        <Zap size={10} className="text-primary" />
                        <p className="text-[10px] font-black text-primary uppercase">+{xp} XP</p>
                    </div>
                </div>
                <p className="text-[12px] text-[var(--muted)] mb-3 leading-snug">{desc}</p>
                <div className="h-1.5 w-full bg-[var(--border)] rounded-full overflow-hidden">
                    <div
                        className={cn("h-full rounded-full transition-all duration-700 relative", completed ? "bg-emerald-500" : "bg-primary")}
                        style={{ width: `${progress}%` }}
                    >
                        {!completed && <div className="absolute inset-0 bg-white/20 animate-[shimmer_2s_infinite]" />}
                    </div>
                </div>
            </div>
        </div>
    );
}

function StatCard({ title, value, change, isPositive, icon: Icon, color, isLarge }: any) {
    const colorMap: any = {
        primary: { bg: "bg-primary/10", text: "text-primary", border: "border-primary/10" },
        emerald: { bg: "bg-emerald-500/10", text: "text-emerald-600", border: "border-emerald-500/10" },
        amber: { bg: "bg-amber-500/10", text: "text-amber-600", border: "border-amber-500/10" },
        indigo: { bg: "bg-indigo-500/10", text: "text-indigo-600", border: "border-indigo-500/10" },
    };
    const c = colorMap[color] || colorMap.primary;

    return (
        <div className={cn(
            "bg-card rounded-2xl border border-[var(--border)] flex flex-col justify-between overflow-hidden shadow-premium-sm hover:shadow-premium transition-all group",
            isLarge ? "p-8" : "p-6"
        )}>
            <div className="flex items-start justify-between mb-6">
                <div className={cn("size-12 rounded-xl flex items-center justify-center transition-transform group-hover:scale-110 shadow-sm", c.bg, c.text)}>
                    <Icon size={isLarge ? 24 : 20} />
                </div>
                <div className={cn(
                    "flex items-center gap-1 px-2.5 py-1 rounded-lg text-[11px] font-black transition-transform group-hover:translate-x-1",
                    isPositive
                        ? "bg-emerald-500/10 text-emerald-600"
                        : "bg-rose-500/10 text-rose-600"
                )}>
                    {isPositive ? <ArrowUpRight size={12} /> : <ArrowDownRight size={12} />}
                    {change}
                </div>
            </div>

            <div>
                <p className="text-[11px] font-black text-[var(--muted)] uppercase tracking-widest mb-1 opacity-80">{title}</p>
                <h4 className={cn("font-black text-[var(--foreground)] tracking-tight", isLarge ? "text-4xl" : "text-2xl")}>{value}</h4>

                {/* Minimalist Sparkline */}
                <div className="mt-6 h-8 w-full opacity-30 group-hover:opacity-60 transition-opacity">
                    <svg viewBox="0 0 100 20" className="w-full h-full preserve-3d">
                        <path
                            d="M0 15 Q 10 5, 20 12 T 40 8 T 60 14 T 80 6 T 100 10"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="2.5"
                            className={c.text}
                            strokeLinecap="round"
                        />
                    </svg>
                </div>
            </div>
        </div>
    );
}
